---FreshUI
---@param data table{
--- vo
--- catData
--- quality
--- goodsNum
---}
---@param context OverseaManageCatBallControlDialog
function OverseaManageCatBallStoreHouse:FreshUI(context, isInit)
    self._context = context
    self:FreshLeftUI(context)

    self:FreshRightUI(isInit)

end

function OverseaManageCatBallStoreHouse:FreshLeftUI(context)
    self:FreshFilterNode(context)
    self:FreshBackpackCapacity(context)
    
end

function OverseaManageCatBallStoreHouse:FreshRightUI(isInit)
    local dataList = self._context:GetCatRollStorehouseList()
    local data     = dataList[self._selectIndex]
    if data == nil then
        self._selectIndex = 1
        data     = dataList[self._selectIndex]
    end
    local isShow   = data ~= nil
    KTool.SetActive(self.RightPanel.gameObject, isShow)
    if not isShow then
        return
    end
    ---@type MaidCoffeeCatRollConfigVo | GoodsVo
    local vo = data.vo
    self.TextName.text = vo.name
    local catData = data.catData
    local isGoods = catData == nil
    KTool.SetActive(self.ImgGoodsIcon.gameObject, isGoods)
    if isGoods then
        self.ImgGoodsIcon:LoadSprite(vo.photoPath)
    end

    self:FreshSkillDesc(catData, vo, isGoods)
    
    self:FreshLockState(catData, isGoods)
    
    self:FreshCatOrGoods(data, isGoods)
end

function OverseaManageCatBallStoreHouse:FreshFilterNode(context)
    local stoneDataList = context:GetCatRollStorehouseList()
    ---@type UICommonFilterMB
    local filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBPath)
    if isNull(filterNodeEnv) then return end
    KTool.SetActive(self.EmptyNode.gameObject, #stoneDataList <= 0)
    --filterNodeEnv:SetStyleType(1)
    filterNodeEnv:SetPageType(Constants.UIFilterPageType.PullUP)
    filterNodeEnv:SetCustomSortCallback(function(dataList, sortType, asc)
        if sortType == Constants.SortType.Quality then
            table.sort(dataList, function(a, b)
                if a.quality ~= b.quality then
                    return CheckField(a.quality, b.quality, asc)
                elseif a.catData and b.catData then
                    if a.catData.star ~= b.catData.star then
                        return CheckField(a.catData.star, b.catData.star, asc)
                    elseif a.catData.level ~= b.catData.level then
                        return CheckField(a.catData.level, b.catData.level, asc)
                    end
                end
                return CheckField(a.vo.id, b.vo.id, asc)
            end)
        end
        return dataList
    end)
    filterNodeEnv:SetCallback(stoneDataList, function(data)
        context:SetCatRollStorehouseList(data)
        KTool.SetActive(self.EmptyNode.gameObject, #data <= 0)
        context:FreshList()

    end, Constants.UISortType.MaidCoffeeCatBallStone)
    filterNodeEnv:SetFilterClass()
    filterNodeEnv:RestoreState("OverseaManageCatBallStoreHouse", function(data)
        context:SetCatRollStorehouseList(data)
        KTool.SetActive(self.EmptyNode.gameObject, #data <= 0)
        context:FreshList()
    end)    
end

function OverseaManageCatBallStoreHouse:FreshBackpackCapacity(context)
    local stoneDataList = context:GetCatRollStorehouseList()
    local curSize       = #stoneDataList
    local capacity      = MaidCoffeeUtils.CalcMaxBackpackCapacity()
    local formatStr     = curSize > capacity and "<color=#ff47ba>%s</color>/%s" or "%s/%s"
    self.TextNumber.text = string.format(formatStr, curSize, capacity)

    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local extendTimes  = eggComponent:GetExtendTimes()
    KTool.SetActive(self.BtnAdd.gameObject, extendTimes < self._maxTimes)
    
end

function OverseaManageCatBallStoreHouse:FreshSkillDesc(catData, vo, isGoods)
    ---@type OverseaManageCatBallSkillDescNode
    local env = CfUtils.GetLuaScr(self.SkillDesc, MaidCoffeeConstants.EnvPath.OverseaManageCatBallSkillDescNode)
    if env then
        if isGoods then
            env:FreshGoodsDesc(vo.desc)
        else
            env:FreshUI(catData, vo)
        end
    end
end

---FreshLockState
---@param catData CatEggDojo
function OverseaManageCatBallStoreHouse:FreshLockState(catData, isGoods, isSwitch)
    KTool.SetActive(self.BtnLock.gameObject, not isGoods)
    if isGoods then
        return 
    end
    local locked = catData.locked == 0
    local animName
    if isSwitch then
        animName = locked and Locking or Unlock
    else
        animName = locked and LockingDefault or UnlockDefault
    end
    self.ImgLock:Play(animName)
    
end

function OverseaManageCatBallStoreHouse:FreshCatOrGoods(data, isGoods)
    KTool.SetActive(self.IconNode.gameObject, isGoods)
    if not isGoods then
        self._context:LoadCatModelAsync(data)
    else
        self._context:StopCoroutine()
        self._context:DeleteCatGameObject()
    end
end

--endregion


--region get/set

function OverseaManageCatBallStoreHouse:GetSelectIndex()
    return self._selectIndex
end
function OverseaManageCatBallStoreHouse:SetSelectIndex(index)
    if self._selectIndex == index then
        return
    end
    local oldIndex = self._selectIndex
    self._selectIndex = index
    self:FreshRightUI()
    return oldIndex
end

--endregion


--region handler

function OverseaManageCatBallStoreHouse:OnClickBtnAddAction()
    

    -- GameUtils.showsce
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local extendTimes  = eggComponent:GetExtendTimes()
    local nexTimes = extendTimes + 1
    ---@type MaidCoffeeCatRollStoreVo
    local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollStoreVo(nexTimes)
    local goods = vo.goods[1];
    local goodsId = goods.goodsId
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    local goodsNum = goods.goodsNum
    GameUtils.SecondConfirm(localize("是否消耗_num_个_name_扩充_num1_个仓库位置？", {_num_ = goodsNum, _name_ = goodsVo.name, _num1_ = vo.placeNum}), function()
        local consume, errTip = GoodsUtils.CheckGoodConsume({ goods })
        if errTip then
            GameUtils.Toast(errTip)
            return
        end
        
        local interface   = Interfaces.MaidCoffeeUnlockCatBackpack
        local requestData = {}
        GameUtils.Request(interface, requestData, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            GoodsUtils.DrawRewards(consume)

            eggComponent:SetExtendTimes(checkNumber(response.data.catBackpackUnlockTimes))
            
            self:FreshBackpackCapacity(self._context)
        end)
    end)

    
    
end

function OverseaManageCatBallStoreHouse:OnClickBtnAction()
    CfUtils.DialogOpen(Constants.UITypeIds.OverseaManageCatballExchangePopup, nil, nil, true)
end

function OverseaManageCatBallStoreHouse:OnClickBtnLockAction()
    local dataList = self._context:GetCatRollStorehouseList()
    local data     = dataList[self._selectIndex]
    if data == nil then
        return
    end
    ---@type CatEggDojo
    local dojo = data.catData
    local playerCatId = dojo.id
    local interface   = Interfaces.MaidCoffeeCatLock
    local res = dojo.locked == 0 and 1 or 0
    local requestData = {playerCatId = dojo.id, status = res}
    GameUtils.Request(interface, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end

        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        data.catData = eggComponent:UpdateCatLocked(playerCatId, res)
            
        self:FreshLockState(dojo, false, true)
        
    end)
end

--endregion

return OverseaManageCatBallStoreHouse